// Search box for an assignable employee (sales head, lead generated by). Types, waits ~300 ms, then asks
// GET /api/admin-panel/employees/lookup/. Picking a row sets only the employee code on the form.
import { useEffect, useRef, useState } from "react"
import PropTypes from "prop-types"
import { Input, Spinner } from "@/components/ui"
import { authFetch } from "@/lib/http"
import { EMPLOYEE_LOOKUP } from "../../api"

const DEBOUNCE_MS = 300

// savedName: the employee name already stored for `value` (edit form), shown until another one is picked
const EmployeeCodePicker = ({ name: fieldName, value, label, invalid, onChange, savedName }) => {
    const [picked, setPicked] = useState(null)
    const [text, setText] = useState(value || "")
    const [open, setOpen] = useState(false)
    const [loading, setLoading] = useState(false)
    const [results, setResults] = useState([])
    const [failed, setFailed] = useState("")
    const box = useRef(null)
    const seq = useRef(0)

    // follow the form value (reset after submit, loaded in the edit form)
    // (skipped for the value this box just emitted itself, or typing would be wiped)
    const lastEmitted = useRef(value || "")
    useEffect(() => {
        if ((value || "") !== lastEmitted.current) {
            lastEmitted.current = value || ""
            setText(value || "")
        }
    }, [value])

    useEffect(() => {
        if (!open) return undefined
        const id = ++seq.current
        const t = setTimeout(async () => {
            setLoading(true)
            setFailed("")
            try {
                const q = text.trim()
                const res = await authFetch(`${EMPLOYEE_LOOKUP}?limit=1000${q ? `&q=${encodeURIComponent(q)}` : ""}`)
                const data = await res.json().catch(() => ({}))
                if (id !== seq.current) return // a newer search has started
                if (!res.ok) {
                    setResults([])
                    setFailed(res.status === 403 ? "You do not have access to search employees" : "Could not load employees")
                } else {
                    setResults(Array.isArray(data?.results) ? data.results : [])
                }
            } catch {
                if (id === seq.current) { setResults([]); setFailed("Could not load employees") }
            } finally {
                if (id === seq.current) setLoading(false)
            }
        }, DEBOUNCE_MS)
        return () => clearTimeout(t)
    }, [text, open])

    useEffect(() => {
        const close = (e) => { if (box.current && !box.current.contains(e.target)) setOpen(false) }
        document.addEventListener("mousedown", close)
        return () => document.removeEventListener("mousedown", close)
    }, [])

    const emit = (code) => onChange({ target: { name: fieldName, value: code, type: "text" } })

    const pick = (emp) => {
        setPicked(emp)
        setText(emp.employee_code)
        emit(emp.employee_code)
        setOpen(false)
    }

    return (
        <div ref={box} className="relative">
            <Input
                type="text"
                autoComplete="off"
                value={text}
                placeholder={`Search ${label} by code or name`}
                invalid={invalid}
                onFocus={() => setOpen(true)}
                onChange={(e) => {
                    setText(e.target.value)
                    setPicked(null)
                    setOpen(true)
                    emit("") // typed but not picked: no code is chosen yet
                }}
            />
            {/* what is selected, in words */}
            {value && (picked?.employee_code === value || savedName) && (
                <div className="mt-1 text-xs text-success-500">
                    ✓ {picked?.employee_code === value
                        ? `${picked.name}${picked.designation ? ` – ${picked.designation}` : ""}${picked.department ? `, ${picked.department}` : ""}`
                        : savedName}
                </div>
            )}
            {!value && text.trim() && !open && (
                <div className="mt-1 text-xs text-warning-500">Pick an employee from the list to select them</div>
            )}
            {open && (
                <div className="absolute left-0 right-0 top-full z-50 mt-1 max-h-60 overflow-auto rounded-md border border-white/10 bg-surface shadow-lg">
                    {loading && <div className="px-3 py-2 text-sm text-ink-muted"><Spinner size="sm" /> Searching...</div>}
                    {!loading && failed && <div className="px-3 py-2 text-sm text-danger-500">{failed}</div>}
                    {!loading && !failed && results.length === 0 && <div className="px-3 py-2 text-sm text-ink-muted">No matching employee</div>}
                    {!loading && results.map((emp) => (
                        <button
                            type="button"
                            key={emp.employee_code}
                            className="block w-full px-3 py-2 text-left text-sm hover:bg-white/5"
                            onClick={() => pick(emp)}
                        >
                            {emp.employee_code} – {emp.name}{emp.designation ? ` (${emp.designation})` : ""}
                        </button>
                    ))}
                </div>
            )}
        </div>
    )
}

EmployeeCodePicker.propTypes = {
    name: PropTypes.string.isRequired,
    value: PropTypes.string,
    label: PropTypes.string,
    invalid: PropTypes.bool,
    savedName: PropTypes.string,
    onChange: PropTypes.func.isRequired,
}

export default EmployeeCodePicker
